# make.fun news-image-01 entry: a newspaper front page summing up the world
# news of Friday 13 November 2026. The image is generated by generator.py (at
# build time) and shipped as entry.png; this entrypoint copies it to /output.
import os
import shutil

src = os.path.join(os.path.dirname(__file__), "entry.png")
out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
os.makedirs(out_dir, exist_ok=True)
shutil.copyfile(src, os.path.join(out_dir, "entry.png"))
print("wrote", os.path.join(out_dir, "entry.png"))
